@@ -0,0 +1,43 @@
+"""Date based argument spec validation for validate-modules."""
+from __future__ import (absolute_import, division, print_function)
+__metaclass__ = type
+
+import pytest
+from voluptuous import MultipleInvalid
+
+from validate_modules.main import ModuleValidator
+from validate_modules.schema import argument_spec_schema
+
+
+@pytest.mark.parametrize('argument', [
+    {'removed_at_date': '2999-12-31'},
+    {'deprecated_aliases': [{'name': 'old', 'date': '2999-12-31'}]},
+    {'deprecated_aliases': [{'name': 'old', 'version': '9.99'}]},
+])
+def test_valid_date_or_version_removal(argument):
+    argument_spec_schema()({'option': argument})
+
+
+@pytest.mark.parametrize('argument', [
+    {'removed_at_date': '2999-02-29'},
+    {'removed_at_date': '2999-1-1'},
+    {'deprecated_aliases': [{'name': 'old'}]},
+    {'deprecated_aliases': [{'name': 'old', 'version': '9.99', 'date': '2999-12-31'}]},
+    {'deprecated_aliases': [{'name': 'old', 'date': '2999-02-29'}]},
+])
+def test_invalid_date_or_ambiguous_removal(argument):
+    with pytest.raises(MultipleInvalid):
+        argument_spec_schema()({'option': argument})
+
+
+@pytest.mark.parametrize('argument,expected_code', [
+    ({'removed_at_date': '2000-01-01'}, 'ansible-deprecated-date'),
+    ({'deprecated_aliases': [{'name': 'old', 'date': '2000-01-01'}]}, 'ansible-deprecated-date'),
+    ({'deprecated_aliases': [{'name': 'old', 'date': '2999-12-31'}]}, None),
+])
+def test_removal_date_validation(argument, expected_code):
+    validator = ModuleValidator(__file__, analyze_arg_spec=True, git_cache=object())
+    validator._validate_argument_spec(None, {'option': argument}, {'argument_spec': {'option': argument}})
+    errors = validator.reporter.files.get(__file__, {}).get('errors', [])
+    date_errors = [error['code'] for error in errors if error['code'].endswith('-date')]
+    assert date_errors == ([expected_code] if expected_code else [])
