+def test_deprecated_removal(capsys, mocker, kwargs, removal):
+    mocker.patch('ansible.utils.color.ANSIBLE_COLOR', False)
+    mocker.patch('ansible.utils.display.C.DEPRECATION_WARNINGS', True)
+    mocker.patch('ansible.utils.display.logger', None)
+
