+    display.deprecated(msg, **kwargs)
+
+    out, err = capsys.readouterr()
+    assert out == ''
+    assert err == ('[DEPRECATION WARNING]: %s. This feature will be removed %s. '
+                   'Deprecation warnings can be disabled by setting deprecation_warnings=False in ansible.cfg.\n') % (msg, removal)
